INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 30, 'theory', 'Quiz: introspection and inspect');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 30, 0, 'How does vars(obj) differ from dir(obj)?', '["No difference, they are synonyms", "vars returns the instance''s own attributes (its __dict__), while dir returns all available names", "dir returns values, vars returns only names", "vars works only with modules"]', 1, 'dir answers "what is available" (including inherited and special names), vars answers "what is stored right here".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 30, 1, 'What does getattr(obj, ''z'', None) return if there is no attribute z?', '["AttributeError", "None", "An empty string", "The value ''z''"]', 1, 'The third argument is the default value: there is no need to catch an attribute error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 30, 2, 'What is the signature.bind(*args, **kwargs) method for?', '["To call the function", "To change the signature", "To find out which values go to which parameters, and get a TypeError on a mismatch", "To copy the function"]', 2, 'bind attaches a call to the signature; argument validation and dependency injection are built on it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 30, 3, 'Where can you find the values captured by a nested function (a closure)?', '["In __doc__", "In __globals__", "In __defaults__", "In __closure__ — cells with cell_contents"]', 3, 'The names of free variables are in __code__.co_freevars, and their values are in the __closure__ cells.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 30, 4, 'What is the right way to get real types from annotations when some of them are strings?', '["Through typing.get_type_hints (and in Python 3.14, through annotationlib)", "Read __annotations__ directly", "Run eval on each string by hand", "Through dir(func)"]', 0, 'The standard getter functions handle deferred and string annotations; the dictionary should not be read directly.');
